import {cowCapacity,cowSupply} from './cow-state.js';
import {cowMilkingReason} from './cow-milking.js';
/** @param {number} ordinal @param {number} tick @param {boolean} [feed] @param {boolean} [water] @param {number} [comfort] */
export function cowActivity(ordinal,tick,feed=true,water=true,comfort=1000){const phases=/** @type {const} */(['idle','walk','eat','drink','rest']),activity=phases[(Math.floor(tick/3)+ordinal)%phases.length];if((activity==='eat'&&!feed)||(activity==='drink'&&!water))return 'idle';return activity==='walk'&&comfort<350?'rest':activity;}
/** Read-only detached presentation of actual saved ownership. @param {import('./engine.js').State} state */
export function cowSnapshot(state){const g=state.cow;return {expanded:!!g?.barn?.expanded,sanitation:!!g?.barn?.sanitation,cooler:{owned:!!g?.cooler.owned,status:g?.cooler.status||'off',storedMl:g?.lots.filter(l=>l.storage==='cooler').reduce((n,l)=>n+l.remainingVolumeMl,0)||0},shade:!!g?.barn?.shade,herd:g?.visited?g.cows.map(c=>({id:c.id,lactating:c.lactationStatus==='lactating',priorCalving:c.priorCalving,milkReadyMl:c.milkReadyMl,canMilk:!cowMilkingReason(state,c.id,'can')||!!g.cooler.owned&&!cowMilkingReason(state,c.id,'cooler'),stage:c.lactationStage,activity:cowActivity(c.id==='cow.starter.a'?0:c.id==='cow.starter.b'?1:2,state.tick,cowSupply(g.feedTrough)>0,cowSupply(g.waterTrough)>0,c.comfort)})):[],capacity:g?cowCapacity(g).cows:2,feedG:g?cowSupply(g.feedTrough):0,waterMl:g?cowSupply(g.waterTrough):0,waterCapacityMl:g?cowCapacity(g).waterMl:100000,canMilkMl:g?.lots.filter(l=>l.storage==='can').reduce((n,l)=>n+l.remainingVolumeMl,0)||0};}
